window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-f2b8889be8c7fd24"]={"versions": [{"id": "FIG-f2b8889be8c7fd24", "releases": ["R19-11", "R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> Strukturelles Entitäts-/Konfigurationsdiagramm (Metamodell-Instanzdarstellung) einer Alive-Supervision-Topologie.</li>\n<li><strong>Funktionale Einordnung:</strong> Definiert die Minimal-Konfiguration für die Alive-Überwachung im AUTOSAR Health Monitoring (FO / Adaptive Platform). Es zeigt die isolierte Überwachung der zyklischen Ausführungsfrequenz einer <em>Supervised Entity</em> (<code>SE3</code>) über einen einzelnen Kontrollpunkt (<code>CP3-1</code>) innerhalb eines aktiven <em>Supervision Mode</em>, ohne Beteiligung von logischen Kontrollfluss-Transitionen.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Supervised Entity (<code>SE3</code>):</strong> Logische Überwachungskapsel auf Applikations- oder Plattformebene (z. B. Prozess, Thread oder periodischer Funktionsblock).</li>\n<li><strong>Checkpoint (<code>CP3-1</code>):</strong> Atomare Instrumentierungsstelle im Programmcode der Entität.</li>\n<li><strong>Konfigurationsattribute (<code>CP3-1</code>):</strong></li>\n<li><code>ExpectedAliveIndications</code>: Normative Soll-Anzahl der Checkpoint-Meldungen innerhalb des Überwachungsintervalls.</li>\n<li><code>MinMargin</code>: Maximal zulässige negative Abweichung (Untergrenze = <code>ExpectedAliveIndications - MinMargin</code>).</li>\n<li><code>MaxMargin</code>: Maximal zulässige positive Abweichung (Obergrenze = <code>ExpectedAliveIndications + MaxMargin</code>).</li>\n<li><code>AliveReferenceCycle</code>: Zeitfenster bzw. Anzahl der zyklischen Health-Monitoring-Hauptzyklen, über die die Indikationen gezählt und bewertet werden.</li>\n<li><strong>Topologie & Kardinalität:</strong> $1:1$-Beziehung im dargestellten Betriebsmodus (genau ein Checkpoint pro Entität, isoliert ohne Transitionskanten).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Zyklischer Trigger (Applikation):</strong> Die überwachte Entität führt periodisch ihren Funktionscode aus und meldet das Erreichen der Code-Position synchron über den API-Aufruf <code>ReportCheckpoint(CP3-1)</code>.</li>\n<li><strong>Akkumulation:</strong> Der Health-Monitoring-Stack inkrementiert bei jedem Aufruf einen internen Zähler <code>aliveCounter</code> für diesen Checkpoint.</li>\n<li><strong>Periodische Evaluierung:</strong> Nach Ablauf der konfigurierten <code>AliveReferenceCycle</code>-Zyklen prüft die <code>MainFunction</code> des Health Monitors:</li>\n</ol>\n<p class=\"fig-p\">$$\\text{ExpectedAliveIndications} - \\text{MinMargin} \\le \\text{aliveCounter} \\le \\text{ExpectedAliveIndications} + \\text{MaxMargin}$$</p>\n<ol class=\"fig-list\">\n<li><strong>Zustandsübergang & Fehlerpfad:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Gültig:</strong> Lokaler Status bleibt <code>ALIVE_OK</code>; <code>aliveCounter</code> wird für den Folgezyklus zurückgesetzt.</li>\n<li><strong>Verletzung:</strong> Lokaler Status wechselt auf <code>ALIVE_FAILED</code> (bzw. nach Erreichen definierter Fehlertoleranzgrenzen <code>ALIVE_EXPIRED</code>). Dies triggert konfigurierte Recovery-Aktionen (z. B. Benachrichtigung des <em>State Management</em> oder Fehlerspeichereintrag).</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Konfigurationsabgleich:</strong> <code>AliveReferenceCycle</code>, <code>ExpectedAliveIndications</code> und Toleranzen müssen mathematisch an die Task-Aktivierungsrate, Betriebssystem-Jitter und maximale Ausführungszeiten (WCET) gekoppelt werden, um Fehlauslösungen durch Scheduling-Verzögerungen zu verhindern.</li>\n<li><strong>API-Vertrag:</strong> Der Entwickler muss <code>ReportCheckpoint(CP3-1)</code> deterministisch im korrekten Ausführungskontext aufrufen. Ein bedingtes Übergehen (z. B. in Verzweigungen) führt zwingend zur Verletzung der Minimalgrenze.</li>\n<li><strong>Funktionale Einschränkung:</strong> Dieses Minimalkonstrukt detektiert ausschließlich das Ausbleiben, Blockieren oder unzulässige Vorauseilen des Aufrufers. Eine logische Flussüberwachung (Reihenfolgekorrektheit) oder Latenzprüfung zwischen zwei Ereignissen (Deadline Supervision) ist ohne zusätzliche Checkpoints und Transitionen per Definition ausgeschlossen.</li>\n</ul>"}, {"id": "FIG-7473795dbc8c30dd", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> Strukturelles Entitäts-/Konfigurationsdiagramm (Metamodell-Instanzdarstellung) einer Alive-Supervision-Topologie.</li>\n<li><strong>Funktionale Einordnung:</strong> Definiert die Minimal-Konfiguration für die Alive-Überwachung im AUTOSAR Health Monitoring (FO / Adaptive Platform). Es zeigt die isolierte Überwachung der zyklischen Ausführungsfrequenz einer <em>Supervised Entity</em> (<code>SE3</code>) über einen einzelnen Kontrollpunkt (<code>CP3-1</code>) innerhalb eines aktiven <em>Supervision Mode</em>, ohne Beteiligung von logischen Kontrollfluss-Transitionen.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Supervised Entity (<code>SE3</code>):</strong> Logische Überwachungskapsel auf Applikations- oder Plattformebene (z. B. Prozess, Thread oder periodischer Funktionsblock).</li>\n<li><strong>Checkpoint (<code>CP3-1</code>):</strong> Atomare Instrumentierungsstelle im Programmcode der Entität, grafisch abgesetzt als eigener Block ohne Attribute.</li>\n<li><strong>Konfigurationsattribute (Alive-Supervision für <code>CP3-1</code>):</strong></li>\n<li><code>ExpectedAliveIndications</code>: Normative Soll-Anzahl der Checkpoint-Meldungen innerhalb des Überwachungsintervalls.</li>\n<li><code>MaxMargin</code>: Maximal zulässige positive Abweichung (Obergrenze = <code>ExpectedAliveIndications + MaxMargin</code>).</li>\n<li><code>MinMargin</code>: Maximal zulässige negative Abweichung (Untergrenze = <code>ExpectedAliveIndications - MinMargin</code>).</li>\n<li><code>AliveReferenceCycle</code>: Zeitfenster bzw. Anzahl der zyklischen Health-Monitoring-Hauptzyklen, über die die Indikationen gezählt und bewertet werden.</li>\n<li><code>FailedReferenceCyclesTolerance</code>: Anzahl aufeinanderfolgender Referenzzyklen mit fehlerhafter Alive-Indikation (<code>ALIVE_FAILED</code>), die toleriert werden, bevor der Zustand endgültig nach <code>ALIVE_EXPIRED</code> wechselt.</li>\n<li><strong>Topologie & Kardinalität:</strong> $1:1$-Beziehung im dargestellten Betriebsmodus (genau ein Checkpoint pro Entität, isoliert ohne Transitionskanten).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Zyklischer Trigger (Applikation):</strong> Die überwachte Entität führt periodisch ihren Funktionscode aus und meldet das Erreichen der Code-Position synchron über den API-Aufruf <code>ReportCheckpoint(CP3-1)</code>.</li>\n<li><strong>Akkumulation:</strong> Der Health-Monitoring-Stack inkrementiert bei jedem Aufruf einen internen Zähler <code>aliveCounter</code> für diesen Checkpoint.</li>\n<li><strong>Periodische Evaluierung:</strong> Nach Ablauf der konfigurierten <code>AliveReferenceCycle</code>-Zyklen prüft die <code>MainFunction</code> des Health Monitors:</li>\n</ol>\n<p class=\"fig-p\">$$\\text{ExpectedAliveIndications} - \\text{MinMargin} \\le \\text{aliveCounter} \\le \\text{ExpectedAliveIndications} + \\text{MaxMargin}$$</p>\n<ol class=\"fig-list\">\n<li><strong>Zustandsübergang & Fehlerpfad:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Gültig:</strong> Lokaler Status bleibt <code>ALIVE_OK</code>; <code>aliveCounter</code> wird für den Folgezyklus zurückgesetzt.</li>\n<li><strong>Verletzung:</strong> Lokaler Status wechselt auf <code>ALIVE_FAILED</code> (bzw. nach Erreichen definierter Fehlertoleranzgrenzen <code>ALIVE_EXPIRED</code>). Dies triggert konfigurierte Recovery-Aktionen (z. B. Benachrichtigung des <em>State Management</em> oder Fehlerspeichereintrag).</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Konfigurationsabgleich:</strong> <code>AliveReferenceCycle</code>, <code>ExpectedAliveIndications</code> und Toleranzen müssen mathematisch an die Task-Aktivierungsrate, Betriebssystem-Jitter und maximale Ausführungszeiten (WCET) gekoppelt werden, um Fehlauslösungen durch Scheduling-Verzögerungen zu verhindern.</li>\n<li><strong>API-Vertrag:</strong> Der Entwickler muss <code>ReportCheckpoint(CP3-1)</code> deterministisch im korrekten Ausführungskontext aufrufen. Ein bedingtes Übergehen (z. B. in Verzweigungen) führt zwingend zur Verletzung der Minimalgrenze.</li>\n<li><strong>Funktionale Einschränkung:</strong> Dieses Minimalkonstrukt detektiert ausschließlich das Ausbleiben, Blockieren oder unzulässige Vorauseilen des Aufrufers. Eine logische Flussüberwachung (Reihenfolgekorrektheit) oder Latenzprüfung zwischen zwei Ereignissen (Deadline Supervision) ist ohne zusätzliche Checkpoints und Transitionen per Definition ausgeschlossen.</li>\n</ul>"}, {"id": "FIG-1352a461097762a9", "releases": ["R22-11", "R23-11", "R24-11", "R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> Strukturelles Entitäts-/Konfigurationsdiagramm (Metamodell-Instanzdarstellung) einer Alive-Supervision-Topologie.</li>\n<li><strong>Funktionale Einordnung:</strong> Definiert die Minimal-Konfiguration für die Alive-Überwachung im AUTOSAR Health Monitoring (FO / Adaptive Platform). Es zeigt die isolierte Überwachung der zyklischen Ausführungsfrequenz einer <em>Supervised Entity</em> (<code>SE3</code>) über einen einzelnen Kontrollpunkt (<code>CP3-1</code>) innerhalb eines aktiven <em>Supervision Mode</em>, ohne Beteiligung von logischen Kontrollfluss-Transitionen.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Supervised Entity (<code>SE3</code>):</strong> Logische Überwachungskapsel auf Applikations- oder Plattformebene (z. B. Prozess, Thread oder periodischer Funktionsblock).</li>\n<li><strong>Checkpoint (<code>CP3-1</code>):</strong> Atomare Instrumentierungsstelle im Programmcode der Entität, grafisch abgesetzt als eigener Block ohne Attribute.</li>\n<li><strong>Konfigurationsattribute (Alive-Supervision für <code>CP3-1</code>):</strong></li>\n<li><code>ExpectedAliveIndications</code>: Normative Soll-Anzahl der Checkpoint-Meldungen innerhalb des Überwachungsintervalls.</li>\n<li><code>MaxMargin</code>: Maximal zulässige positive Abweichung (Obergrenze = <code>ExpectedAliveIndications + MaxMargin</code>).</li>\n<li><code>MinMargin</code>: Maximal zulässige negative Abweichung (Untergrenze = <code>ExpectedAliveIndications - MinMargin</code>).</li>\n<li><code>AliveReferenceCycle</code>: Zeitfenster bzw. Anzahl der zyklischen Health-Monitoring-Hauptzyklen, über die die Indikationen gezählt und bewertet werden.</li>\n<li><code>FailedReferenceCyclesTolerance</code>: Anzahl aufeinanderfolgender Referenzzyklen mit fehlerhafter Alive-Indikation (<code>ALIVE_FAILED</code>), die toleriert werden, bevor der Zustand endgültig nach <code>ALIVE_EXPIRED</code> wechselt.</li>\n<li><strong>Topologie & Kardinalität:</strong> $1:1$-Beziehung im dargestellten Betriebsmodus (genau ein Checkpoint pro Entität, isoliert ohne Transitionskanten).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Zyklischer Trigger (Applikation):</strong> Die überwachte Entität führt periodisch ihren Funktionscode aus und meldet das Erreichen der Code-Position synchron über den API-Aufruf <code>ReportCheckpoint(CP3-1)</code>.</li>\n<li><strong>Akkumulation:</strong> Der Health-Monitoring-Stack inkrementiert bei jedem Aufruf einen internen Zähler <code>aliveCounter</code> für diesen Checkpoint.</li>\n<li><strong>Periodische Evaluierung:</strong> Nach Ablauf der konfigurierten <code>AliveReferenceCycle</code>-Zyklen prüft die <code>MainFunction</code> des Health Monitors:</li>\n</ol>\n<p class=\"fig-p\">$$\\text{ExpectedAliveIndications} - \\text{MinMargin} \\le \\text{aliveCounter} \\le \\text{ExpectedAliveIndications} + \\text{MaxMargin}$$</p>\n<ol class=\"fig-list\">\n<li><strong>Zustandsübergang & Fehlerpfad:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Gültig:</strong> Lokaler Status bleibt <code>ALIVE_OK</code>; <code>aliveCounter</code> wird für den Folgezyklus zurückgesetzt.</li>\n<li><strong>Verletzung:</strong> Lokaler Status wechselt auf <code>ALIVE_FAILED</code> (bzw. nach Erreichen definierter Fehlertoleranzgrenzen <code>ALIVE_EXPIRED</code>). Dies triggert konfigurierte Recovery-Aktionen (z. B. Benachrichtigung des <em>State Management</em> oder Fehlerspeichereintrag).</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Konfigurationsabgleich:</strong> <code>AliveReferenceCycle</code>, <code>ExpectedAliveIndications</code> und Toleranzen müssen mathematisch an die Task-Aktivierungsrate, Betriebssystem-Jitter und maximale Ausführungszeiten (WCET) gekoppelt werden, um Fehlauslösungen durch Scheduling-Verzögerungen zu verhindern.</li>\n<li><strong>API-Vertrag:</strong> Der Entwickler muss <code>ReportCheckpoint(CP3-1)</code> deterministisch im korrekten Ausführungskontext aufrufen. Ein bedingtes Übergehen (z. B. in Verzweigungen) führt zwingend zur Verletzung der Minimalgrenze.</li>\n<li><strong>Funktionale Einschränkung:</strong> Dieses Minimalkonstrukt detektiert ausschließlich das Ausbleiben, Blockieren oder unzulässige Vorauseilen des Aufrufers. Eine logische Flussüberwachung (Reihenfolgekorrektheit) oder Latenzprüfung zwischen zwei Ereignissen (Deadline Supervision) ist ohne zusätzliche Checkpoints und Transitionen per Definition ausgeschlossen.</li>\n</ul>"}], "trans": [{"from": "FIG-f2b8889be8c7fd24", "to": "FIG-7473795dbc8c30dd", "fr": "R20-11", "tr": "R21-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li><code>SE3</code> / Alive-Supervision: Konfigurationsparameter <code>+ FailedReferenceCyclesTolerance</code> neu hinzugefügt.</li>\n<li><code>CP3-1</code>: Konfigurationsattribute aus der Checkpoint-Box ausgelagert und darunter innerhalb der Supervised Entity <code>SE3</code> angeordnet.</li>\n<li>Darstellung: Farbschema von beige/braun auf neutrale Graustufendarstellung umgestellt.</li>\n</ul>"}, {"from": "FIG-7473795dbc8c30dd", "to": "FIG-1352a461097762a9", "fr": "R21-11", "tr": "R22-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
